.research.sentiment-workspace{max-width:1320px;color:#202631}
.sentiment-workspace .research-head{margin:0 0 26px;gap:24px}
.sentiment-workspace h1{font-size:32px;letter-spacing:-1px;margin:10px 0 6px}
.sentiment-workspace .subtitle,.sentiment-workspace .section-heading p,.sentiment-workspace .workspace-heading p{color:#667085;margin:6px 0;font-size:14px}
.sentiment-workspace{width:100%;min-width:0;box-sizing:border-box}
.sentiment-workspace .research-head>div{flex:1 1 320px;min-width:0}
.sentiment-workspace h1{font-size:32px;letter-spacing:0;overflow-wrap:anywhere}
.sentiment-workspace .subtitle{max-width:64ch;overflow-wrap:anywhere}
.sentiment-workspace .sentiment-back{display:inline-flex;align-items:center;min-height:44px;font-size:12px;text-decoration:none;color:#667085;font-weight:600}
.sentiment-workspace .research-head>.button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;white-space:nowrap}
.sentiment-workspace .sentiment-tabs{display:flex;flex-wrap:nowrap;gap:28px;width:100%;min-width:0;border-bottom:1px solid #dce1e8;margin-bottom:28px;overflow-x:auto;overscroll-behavior-inline:contain;scrollbar-width:none;-ms-overflow-style:none}
.sentiment-workspace .sentiment-tabs::-webkit-scrollbar{display:none}
.sentiment-workspace .sentiment-tabs a{display:flex;align-items:center;flex:none;min-height:44px;padding:8px 0;text-decoration:none;color:#667085;font-size:14px;white-space:nowrap;font-weight:600;border-bottom:3px solid transparent}
.sentiment-workspace .sentiment-tabs a[aria-current]{color:#b42318;border-bottom-color:#450d07}

.sentiment-workspace .quality-grid span{font-size:13px;color:#667085;font-weight:600}

.sentiment-workspace .panel{min-width:0;border:1px solid #e1e5eb;border-radius:14px;padding:clamp(16px,2vw,24px);box-shadow:0 3px 12px #18223003}
.sentiment-workspace .section-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.sentiment-workspace .distribution-heading>div{min-width:0}
.sentiment-workspace .distribution-panel{width:100%;min-width:0}
.sentiment-workspace h2{font-size:18px;letter-spacing:-.25px;margin:0}
.sentiment-workspace .section-heading a{font-size:13px;font-weight:600;color:#b42318;text-decoration:none}
.sentiment-workspace .soft-badge{font-size:11px;padding:5px 9px;background:#f1f3f6;border-radius:6px;color:#515c6c;white-space:nowrap;font-weight:600}
.sentiment-workspace .distribution-body{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;gap:clamp(24px,5vw,72px);padding:24px 0 12px}
.sentiment-workspace .sentiment-donut{justify-self:center;width:min(100%,200px);aspect-ratio:1;border-radius:50%;background:conic-gradient(#21866c 0 var(--positive),#94a3b8 var(--positive) var(--neutral),#db675d var(--neutral) 100%);display:grid;place-items:center}
.sentiment-workspace .sentiment-donut>div{box-sizing:border-box;width:76%;aspect-ratio:1;border-radius:50%;background:white;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:8px;text-align:center}
.sentiment-workspace .sentiment-donut strong{font-size:32px;line-height:1.1;letter-spacing:0;overflow-wrap:anywhere}.sentiment-workspace .sentiment-donut span{font-size:11px;line-height:1.3;color:#667085}
.sentiment-workspace .sentiment-legend{width:100%;min-width:0}.sentiment-workspace .sentiment-legend>div{display:flex;justify-content:space-between;gap:18px;min-height:44px;padding:12px 0;border-bottom:1px solid #edf0f4;font-size:13px}
.sentiment-workspace .sentiment-legend small{color:#667085;font-size:11px;font-weight:400;margin-left:8px}
.sentiment-workspace .sentiment-dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:8px}.sentiment-workspace .positive{background:#21866c}.sentiment-workspace .neutral{background:#94a3b8}.sentiment-workspace .negative{background:#db675d}
.sentiment-workspace .distribution-footnote{margin:8px 0 0}
.sentiment-workspace .quality-heading>div{min-width:0}
.sentiment-workspace .quality-explore{display:inline-flex;align-items:center;min-height:44px}
.sentiment-workspace .quality-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:24px;gap:0}
.sentiment-workspace .quality-grid>div{min-width:0;padding:14px 16px;border-top:1px solid #eceff3;border-inline-start:1px solid #eceff3}
.sentiment-workspace .quality-grid>div:nth-child(4n+1){border-inline-start:0}
.sentiment-workspace .quality-grid strong{display:block;font-size:28px;line-height:1.2;margin-top:8px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.sentiment-workspace .workspace-heading{margin:26px 0 20px}.sentiment-workspace .feedback-filters{display:flex;align-items:end;gap:14px;padding:18px;background:white;border:1px solid #e1e5eb;border-radius:12px;flex-wrap:wrap}.sentiment-workspace .feedback-filters label{margin:0;flex:1;min-width:170px}.sentiment-workspace .feedback-filters input,.sentiment-workspace .feedback-filters select{margin-top:8px}.sentiment-workspace .feedback-filters>a{padding:10px;font-size:13px;color:#667085}
.sentiment-workspace .feedback-cards{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:18px 0}.sentiment-workspace .feedback-card{margin:0;display:flex;flex-direction:column}.sentiment-workspace .feedback-code{font-size:13px;letter-spacing:.8px}.sentiment-workspace .feedback-excerpt{font-size:15px;line-height:1.7;overflow-wrap:anywhere;flex:1}.sentiment-workspace .feedback-meta{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:18px 0}.sentiment-workspace dt{font-size:11px;color:#667085}.sentiment-workspace dd{font-size:12px;font-weight:600;margin:5px 0;overflow-wrap:anywhere}.sentiment-workspace .feedback-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-top:16px;border-top:1px solid #edf0f4}.sentiment-workspace .empty-state{grid-column:1/-1;text-align:center;padding:48px}.sentiment-workspace .engine-details{background:#f8f9fb;box-shadow:none}.sentiment-workspace .engine-details summary{font-size:13px;color:#515c6c}.sentiment-workspace .engine-details .soft-badge{margin-left:10px}.sentiment-workspace a.button,.sentiment-workspace button{border-radius:8px;font-weight:600}.sentiment-workspace a.primary,.sentiment-workspace button.primary{background:#b42318;border-color:#b42318;color:white}.sentiment-workspace a.button:hover,.sentiment-workspace button:hover{filter:brightness(.95)}
.check-green,.check-yellow,.check-red{display:inline-block;padding:3px 7px;border-radius:4px;font-weight:700;font-size:12px}.check-green{color:#166534;background:#dcfce7}.check-yellow{color:#92400e;background:#fef3c7}.check-red{color:#991b1b;background:#fee2e2}
@media(max-width:1023px){.sentiment-workspace .quality-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sentiment-workspace .quality-grid>div:nth-child(4n+1){border-inline-start:1px solid #eceff3}.sentiment-workspace .quality-grid>div:nth-child(2n+1){border-inline-start:0}}
@media(max-width:767px){.sentiment-workspace .sentiment-tabs{gap:22px}.sentiment-workspace .feedback-cards{grid-template-columns:1fr}.sentiment-workspace .feedback-meta{grid-template-columns:1fr 1fr}}
@media(max-width:639px){.sentiment-workspace .research-head>.button{width:100%}.sentiment-workspace .sentiment-tabs{gap:18px}.sentiment-workspace .distribution-body{grid-template-columns:minmax(0,1fr);gap:18px}.sentiment-workspace .sentiment-donut{width:min(100%,180px)}.sentiment-workspace .quality-heading{align-items:flex-start;flex-direction:column}.sentiment-workspace .quality-grid{grid-template-columns:minmax(0,1fr)}.sentiment-workspace .quality-grid>div,.sentiment-workspace .quality-grid>div:nth-child(4n+1),.sentiment-workspace .quality-grid>div:nth-child(2n+1){border-inline-start:0}.sentiment-workspace .quality-grid strong{font-size:24px}}
@media(max-width:430px){.sentiment-workspace .feedback-footer{flex-wrap:wrap}}
